package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.*;
import org.springframework.transaction.annotation.*;
import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Business-date daily facts have independent snapshots; a monthly amount is never used as a daily amount. */
@Service @Transactional
public class FinanceDailyInsightService {
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext database;private final AccessPolicy access;private final AuditWriter audit;private final FinanceInsightService monthly;private final FinanceAnalysisGateway model;private final TransactionTemplate transactions;
 public FinanceDailyInsightService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext database,AccessPolicy access,AuditWriter audit,FinanceInsightService monthly,FinanceAnalysisGateway model,PlatformTransactionManager manager){this.jdbc=jdbc;this.database=database;this.access=access;this.audit=audit;this.monthly=monthly;this.model=model;transactions=new TransactionTemplate(manager);}
 private TenantPrincipal prepare(){access.requireAnyPermission("finance.read","finance.accounting.read","finance.configure");var p=access.principal();database.apply(p.tenantId());return p;}
 private static void day(LocalDate date){if(date==null||date.getYear()<2000||date.getYear()>9998)throw bad("日报业务日期无效");}
 public Map<String,Object> dashboard(LocalDate date,UUID hotel){var p=prepare();day(date);if(hotel!=null)access.requireOrgScope(hotel);var b=base(p).addValue("date",date).addValue("hotel",hotel);var books=jdbc.queryForList("select b.*,h.name hotel_name from fa_book b join org_unit h on h.tenant_id=b.tenant_id and h.id=b.hotel_id where b.tenant_id=:tenant and b.enabled and (:tenantScope or b.hotel_id in (:scopes)) and (cast(:hotel as uuid) is null or b.hotel_id=:hotel) order by b.hotel_id,b.id",b);var hotels=new LinkedHashSet<UUID>();var lines=new ArrayList<Map<String,Object>>();var facts=new ArrayList<Map<String,Object>>();var cashRows=new ArrayList<Map<String,Object>>();var channelRows=new ArrayList<Map<String,Object>>();
  for(var book:books){UUID bookId=id(book.get("id")),hotelId=id(book.get("hotel_id")),company=id(book.get("company_id"));hotels.add(hotelId);var q=base(p).addValue("book",bookId).addValue("hotel",hotelId).addValue("company",company).addValue("date",date);boolean started=!date.isBefore(((java.sql.Date)book.get("start_month")).toLocalDate());
   var batches=jdbc.queryForList("select id,source,channel,revision,source_hash,control_total,expected_count,night_audit_date from fb_revenue_batch where tenant_id=:tenant and hotel_id=:hotel and company_id=:company and business_date=:date and status='CONFIRMED' order by source,channel,id",q);
   var channels=jdbc.queryForList("select e.channel,e.kind,count(*) source_count,sum(e.amount) gross_amount,sum(e.net_amount) net_amount,sum(e.commission) commission,sum(e.fee) fee from fb_revenue_entry e join fb_revenue_batch batch on batch.tenant_id=e.tenant_id and batch.id=e.batch_id where e.tenant_id=:tenant and e.hotel_id=:hotel and e.company_id=:company and batch.business_date=:date and batch.status='CONFIRMED' and e.active group by e.channel,e.kind order by e.channel,e.kind",q);for(var channel:channels){channel.put("hotelId",hotelId);channel.put("companyId",company);channel.put("businessDate",date);channelRows.add(output(channel));}
   BigDecimal pmsRevenue=channels.stream().filter(r->Set.of("INCOME","AR").contains(r.get("kind"))).map(r->amount(r.get("net_amount"))).reduce(BigDecimal.ZERO,BigDecimal::add);String pmsVersion="DAILY_PMS:"+FinanceService.hash(json(output(Map.of("batches",batches,"channels",channels))));
   var ledger=started?jdbc.queryForList("select v.id,v.version,v.kind,l.line_no,a.category,l.debit,l.credit from fa_voucher v join fa_voucher_line l on l.tenant_id=v.tenant_id and l.voucher_id=v.id join fa_account a on a.tenant_id=l.tenant_id and a.id=l.account_id where v.tenant_id=:tenant and v.book_id=:book and v.status='POSTED' and v.accounting_date=:date and v.kind not in ('YEAR_CLOSE','YEAR_CLOSE_REVERSAL') order by v.id,l.line_no",q):List.<Map<String,Object>>of();
   BigDecimal revenue=BigDecimal.ZERO,cost=BigDecimal.ZERO;for(var entry:ledger){if("REVENUE".equals(entry.get("category")))revenue=revenue.add(amount(entry.get("credit")).subtract(amount(entry.get("debit"))));if("EXPENSE".equals(entry.get("category")))cost=cost.add(amount(entry.get("debit")).subtract(amount(entry.get("credit"))));}String ledgerVersion="DAILY_POSTED:"+FinanceService.hash(json(value(ledger)));
   var events=cashEvents(p,hotelId,company,date);BigDecimal incoming=BigDecimal.ZERO,outgoing=BigDecimal.ZERO;for(var event:events)if("IN".equals(event.get("direction")))incoming=incoming.add(amount(event.get("amount")));else outgoing=outgoing.add(amount(event.get("amount")));String cashVersion="DAILY_CASH:"+FinanceService.hash(json(value(events)));
   var line=new LinkedHashMap<String,Object>();line.put("bookId",bookId);line.put("hotelId",hotelId);line.put("hotelName",book.get("hotel_name"));line.put("companyId",company);line.put("date",date);line.put("nightAuditDates",batches.stream().map(r->r.get("night_audit_date")).distinct().toList());line.put("confirmedSourceBatches",batches.size());line.put("pmsNetRevenue",batches.isEmpty()?null:pmsRevenue);line.put("postedRevenue",ledger.isEmpty()?null:revenue);line.put("postedExpense",ledger.isEmpty()?null:cost);line.put("postedNetProfit",ledger.isEmpty()?null:revenue.subtract(cost));line.put("registeredCashIn",events.isEmpty()?null:incoming);line.put("registeredCashOut",events.isEmpty()?null:outgoing);line.put("registeredCashNet",events.isEmpty()?null:incoming.subtract(outgoing));line.put("sourceVersion",pmsVersion);line.put("ledgerVersion",ledgerVersion);line.put("cashSourceVersion",cashVersion);line.put("sourceStatus",batches.isEmpty()?"SOURCE_NOT_IMPORTED":"CONFIRMED_IMPORTED_BATCHES_NOT_GUARANTEED_COMPLETE_PMS");line.put("ledgerStatus",!started?"BEFORE_BOOK_START":ledger.isEmpty()?"NO_POSTED_DAILY_ENTRIES":"OBSERVED_POSTED_ENTRIES_NOT_FINAL_DAILY_COST");line.put("cashStatus",events.isEmpty()?"NO_REGISTERED_CASH_SOURCE":"REGISTERED_CASH_NOT_BANK_COMPLETENESS");lines.add(line);
   add(facts,hotelId,company,"PMS_NET_REVENUE","当日已确认来源营业收入",line.get("pmsNetRevenue"),pmsVersion,"按PMS业务日期取已确认当前修订；押金/预收/储值/消费核销不重复算收入，未导入不是零");add(facts,hotelId,company,"POSTED_REVENUE","当日已过账收入",line.get("postedRevenue"),ledgerVersion,"按记账日取当日真实已过账分录，不与PMS收入相加，来源尚未齐不代表完整营业收入");add(facts,hotelId,company,"POSTED_EXPENSE","当日已过账成本费用",line.get("postedExpense"),ledgerVersion,"按记账日，不把采购支付当当日费用；无当日分录留空，不能以月成本除天数造当日成本");add(facts,hotelId,company,"POSTED_NET_PROFIT","当日已过账净损益",line.get("postedNetProfit"),ledgerVersion,"已过账收入减已过账费用，非严格经营利润或已完成日结保证");
   for(String key:List.of("registeredCashIn","registeredCashOut","registeredCashNet"))add(facts,hotelId,company,key,switch(key){case "registeredCashIn"->"当日已登记现金流入";case "registeredCashOut"->"当日已登记现金流出";default->"当日已登记现金净流";},line.get(key),cashVersion,"原现金按实际发生日，登记差错按独立更正记账日列负额；借款抵报销/储值消费/非现金抵货不算新现金；未登记/银行未归属不能推断不存在");
   for(var fact:facts)if(hotelId.equals(fact.get("hotelId"))&&!fact.get("label").toString().startsWith(date+" · "))fact.put("label",date+" · "+fact.get("label"));
   // Only aggregate source families leave this service; no employee/customer names or individual cash rows.
   var grouped=new LinkedHashMap<String,Map<String,Object>>();for(var event:events){String key=event.get("source_kind")+":"+event.get("direction");var row=grouped.computeIfAbsent(key,k->{var r=new LinkedHashMap<String,Object>();r.put("hotelId",hotelId);r.put("companyId",company);r.put("date",date);r.put("sourceKind",event.get("source_kind"));r.put("direction",event.get("direction"));r.put("amount",BigDecimal.ZERO);r.put("sourceCount",0);r.put("sourceVersion",cashVersion);return r;});row.put("amount",amount(row.get("amount")).add(amount(event.get("amount"))));row.put("sourceCount",((Number)row.get("sourceCount")).intValue()+1);}cashRows.addAll(grouped.values());
  }
  var expectedHotels=jdbc.queryForList("select id,name from org_unit where tenant_id=:tenant and status='ACTIVE' and unit_type='HOTEL' and (:tenantScope or id in (:scopes)) and (cast(:hotel as uuid) is null or id=:hotel)",b);boolean completeBookScope=expectedHotels.stream().allMatch(h->hotels.contains(id(h.get("id"))));
  var missingBooks=expectedHotels.stream().map(h->id(h.get("id"))).filter(h->!hotels.contains(h)).toList();for(UUID missingHotel:missingBooks){hotels.add(missingHotel);add(facts,missingHotel,null,"BOOK_SOURCE_UNAVAILABLE",date+" · 门店账套未配置，日报来源不可判断",null,"NO_BOOK:"+missingHotel,"所选授权门店缺真实账套，必须保留其缺数事实与范围，不能把它从集团范围静默移除");}
  var groups=new ArrayList<Map<String,Object>>();for(String field:List.of("pmsNetRevenue","postedRevenue","postedExpense","postedNetProfit","registeredCashIn","registeredCashOut","registeredCashNet")){boolean complete=completeBookScope&&!lines.isEmpty()&&lines.stream().allMatch(r->r.get(field)!=null);var row=new LinkedHashMap<String,Object>();row.put("metric",field);row.put("value",complete?lines.stream().map(r->amount(r.get(field))).reduce(BigDecimal.ZERO,BigDecimal::add):null);row.put("completeScope",complete);row.put("meaning",complete?"仅同一授权账套范围已登记来源之和，非集团正式合并或来源完整保证":"至少一个门店缺账套或当日来源，集团合计留空；不能把部分门店当完整集团日报");groups.add(row);}
  String groupVersion="DAY_GROUP:"+FinanceService.hash(json(Map.of("rows",lines,"missingBookHotelIds",missingBooks)));for(var group:groups){var fact=new LinkedHashMap<String,Object>();fact.put("id","DAY:GROUP:"+group.get("metric"));fact.put("label",date+" · 同范围集团已登记来源合计 · "+group.get("metric"));fact.put("value",group.get("value"));fact.put("complete",false);fact.put("registeredSourceAvailable",group.get("value")!=null);fact.put("unit","CNY");fact.put("sourceReportVersion",groupVersion);fact.put("explanation",group.get("meaning"));facts.add(fact);}
  var data=new LinkedHashMap<String,Object>();data.put("periodKind","DAY");data.put("date",date);data.put("month",YearMonth.from(date).toString());data.put("scope",new ArrayList<>(hotels));data.put("currency","CNY");data.put("amountUnit","YUAN");data.put("dateBasis","PMS_BUSINESS_DATE_LEDGER_ACCOUNTING_DATE_ORIGINAL_CASH_OCCURRED_DATE_CORRECTIONS_ACCOUNTING_DATE");data.put("groupBasis","MANAGEMENT_SUMMARY_NOT_STATUTORY_CONSOLIDATION");data.put("status",lines.isEmpty()?"NO_BOOK":"PRELIMINARY_DAILY_REGISTERED_SOURCES");data.put("facts",facts);data.put("dailyOperating",lines);data.put("dailyGroup",groups);data.put("dailyCash",cashRows);data.put("channels",channelRows);data.put("books",List.of());data.put("budgetExecution",List.of());data.put("aging",List.of());data.put("cashPlan",List.of());data.put("revenueReconciliation",List.of());data.put("missingReasons",List.of("没有已确认当日批次不是零收入；未自动连接PMS","已登记现金不等于银行资料齐全；无现金来源时留空","日报为业务日期/记账日/实际资金日分别说明的快报，不把月报重新标注为当日"));data.put("reportVersion",FinanceService.hash(json(output(data))));data.put("generatedAt",Instant.now().toString());return output(data);
 }
 private static void add(List<Map<String,Object>> facts,UUID hotel,UUID company,String code,String label,Object value,String version,String reason){var row=new LinkedHashMap<String,Object>();row.put("id","DAY:"+hotel+":"+company+":"+code);row.put("hotelId",hotel);row.put("companyId",company);row.put("label",label);row.put("value",value);row.put("complete",false);row.put("registeredSourceAvailable",value!=null);row.put("unit","CNY");row.put("sourceReportVersion",version);row.put("explanation",reason);facts.add(row);}
 private List<Map<String,Object>> cashEvents(TenantPrincipal p,UUID hotel,UUID company,LocalDate date){var parts=new ArrayList<String>();String offset=" and not exists(select 1 from fc_claim_loan_clear c where c.tenant_id=pay.tenant_id and c.payment_id=pay.id)";
  parts.add("select a.id,'OPERATION' source_kind,case when a.action in ('RECEIPT','REPAYMENT') or a.action='REFUND' and d.type<>'REVENUE' then 'IN' else 'OUT' end direction,a.amount from fo_action a join fo_document d on d.tenant_id=a.tenant_id and d.id=a.document_id where a.tenant_id=:tenant and d.hotel_id=:hotel and d.company_id=:company and a.occurred_on=:date and a.action in ('PAYMENT','RECEIPT','REFUND','REPAYMENT')");
  parts.add("select pay.id,'CLAIM','OUT',pay.amount from finance_payment pay join finance_claim c on c.tenant_id=pay.tenant_id and c.id=pay.claim_id where pay.tenant_id=:tenant and c.hotel_id=:hotel and c.company_id=:company and pay.paid_on=:date"+offset);
  parts.add("select m.id,'REVENUE',case when m.kind='RECEIPT' then 'IN' else 'OUT' end,m.amount from fb_revenue_movement m join fb_revenue_entry e on e.tenant_id=m.tenant_id and e.id=m.entry_id where m.tenant_id=:tenant and e.hotel_id=:hotel and e.company_id=:company and m.occurred_on=:date and m.kind in ('RECEIPT','REFUND')");
  parts.add("select pay.id,'PAYROLL','OUT',pay.amount from fb_payroll_payment pay join fb_payroll_line l on l.tenant_id=pay.tenant_id and l.id=pay.line_id join fb_payroll_batch b on b.tenant_id=l.tenant_id and b.id=l.batch_id where pay.tenant_id=:tenant and b.hotel_id=:hotel and b.company_id=:company and pay.occurred_on=:date");
  parts.add("select pay.id,'TAX','OUT',pay.amount from ft_tax_payment pay where pay.tenant_id=:tenant and pay.hotel_id=:hotel and pay.company_id=:company and pay.occurred_on=:date");
  for(String table:List.of("fb_opening_clearing","fb_intercompany_settlement"))parts.add("select c.id,'"+(table.equals("fb_opening_clearing")?"OPENING":"INTERCOMPANY")+"',case when c.kind='RECEIPT' then 'IN' else 'OUT' end,c.amount from "+table+" c where c.tenant_id=:tenant and c.hotel_id=:hotel and c.company_id=:company and c.occurred_on=:date");
  parts.add("select c.id,'FB_CORRECTION',case when c.original_kind='RECEIPT' then 'IN' else 'OUT' end,-c.amount from fb_cash_correction c where c.tenant_id=:tenant and c.hotel_id=:hotel and c.company_id=:company and c.accounting_on=:date and c.original_kind in ('RECEIPT','PAYMENT','REFUND')");
  parts.add("select x.id,'FO_CORRECTION',case when a.action in ('RECEIPT','REPAYMENT') or a.action='REFUND' and d.type<>'REVENUE' then 'IN' else 'OUT' end,-x.amount from fx_cash_correction x join fo_action a on a.tenant_id=x.tenant_id and a.id=x.source_id join fo_document d on d.tenant_id=a.tenant_id and d.id=a.document_id where x.tenant_id=:tenant and x.hotel_id=:hotel and d.company_id=:company and x.source_kind='OPERATION' and x.status='CONFIRMED' and x.accounting_on=:date");
  parts.add("select x.id,'CLAIM_CORRECTION','OUT',-x.amount from fx_cash_correction x join finance_payment pay on pay.tenant_id=x.tenant_id and pay.id=x.source_id join finance_claim claim on claim.tenant_id=pay.tenant_id and claim.id=pay.claim_id where x.tenant_id=:tenant and x.hotel_id=:hotel and claim.company_id=:company and x.source_kind='CLAIM' and x.status='CONFIRMED' and x.accounting_on=:date"+offset);
  parts.add("select s.id,'SUPPLY_REFUND','IN',s.amount from fs_settlement s join fs_return r on r.tenant_id=s.tenant_id and r.id=s.return_id join fs_recognition recognition on recognition.tenant_id=r.tenant_id and recognition.id=r.recognition_id where s.tenant_id=:tenant and r.hotel_id=:hotel and recognition.company_id=:company and s.kind='REFUND' and s.bank_transaction_id is not null and s.business_date=:date");
  return jdbc.queryForList("select * from ("+String.join(" union all ",parts)+") cash order by source_kind,id",base(p).addValue("hotel",hotel).addValue("company",company).addValue("date",date));
 }
 public Map<String,Object> freeze(FinanceDailyInsightModels.Freeze in){var p=prepare();var data=dashboard(in.date(),in.hotelId());if(!in.expectedReportVersion().equals(data.get("reportVersion")))throw conflict("日报来源已变化，请刷新后冻结");if(((List<?>)data.get("scope")).isEmpty()||rows(data.get("dailyOperating")).isEmpty())throw bad("无授权日报账套来源，不能冻结空范围");String hotels="{"+String.join(",",((List<?>)data.get("scope")).stream().map(Object::toString).toList())+"}";var b=base(p).addValue("id",in.requestId()).addValue("month",in.date().withDayOfMonth(1)).addValue("date",in.date()).addValue("hotels",hotels).addValue("version",in.expectedReportVersion()).addValue("facts",json(data));var prior=jdbc.queryForList("select report_version from fi_snapshot where tenant_id=:tenant and id=:id",b);if(!prior.isEmpty()&&!in.expectedReportVersion().equals(prior.getFirst().get("report_version")))throw conflict("冻结请求号已用于其他来源版本");jdbc.update("insert into fi_snapshot(id,tenant_id,month,period_kind,period_date,hotel_ids,report_version,facts,created_by) values(:id,:tenant,:month,'DAY',:date,cast(:hotels as uuid[]),:version,cast(:facts as jsonb),:actor) on conflict(tenant_id,report_version) do nothing",b);UUID id=jdbc.queryForObject("select id from fi_snapshot where tenant_id=:tenant and report_version=:version",b,UUID.class);audit.record("FINANCE_DAILY_SNAPSHOT_FROZEN","FI_SNAPSHOT",id,json(Map.of("date",in.date(),"reportVersion",in.expectedReportVersion())));return Map.of("snapshotId",id,"reportVersion",in.expectedReportVersion());}
 public Map<String,Object> snapshot(UUID id){var result=monthly.snapshot(id);if(!"DAY".equals(result.get("periodKind")))throw bad("所选快照不是日经营/现金日报");return result;}
 public Map<String,Object> snapshots(LocalDate date){var p=prepare();day(date);return output(Map.of("items",jdbc.queryForList("select id,period_date,report_version,created_at from fi_snapshot where tenant_id=:tenant and period_kind='DAY' and period_date=:date and (:tenantScope or hotel_ids <@ array[:scopes]::uuid[]) order by created_at desc,id",base(p).addValue("date",date))));}
 public FinanceAccountingService.ExportFile export(LocalDate date,UUID hotel,UUID snapshot,String version,String format){var data=snapshot==null?dashboard(date,hotel):snapshot(snapshot);if(!version.equals(data.get("reportVersion")))throw conflict("日报版本已变化，停止导出其他版本");var file=new FinanceAccountingService.ExportFile("财务经营现金日报-"+data.get("date")+"."+format,format.equals("xlsx")?"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":"application/pdf",FinanceInsightExportRenderer.render(data,format),version);audit.record("FINANCE_DAILY_EXPORTED","FI_SNAPSHOT",snapshot,json(Map.of("date",data.get("date"),"reportVersion",version,"format",format)));return file;}
 @Transactional(propagation=Propagation.NOT_SUPPORTED)
 public Map<String,Object> ask(FinanceDailyInsightModels.Question in){var frozen=transactions.execute(s->snapshot(in.snapshotId()));if(!in.date().toString().equals(Objects.toString(frozen.get("date")))||!in.expectedReportVersion().equals(frozen.get("reportVersion")))throw conflict("日报日期或来源版本与所选冻结快照不一致");if(!in.allowAggregateTransfer())throw bad("请明确授权本次日报汇总问数");if(in.question()==null||in.question().isBlank()||in.question().matches("(?is).*(\\b(select|insert|update|delete|drop|alter|truncate|execute|union)\\b|information_schema|(?:finance|fa|fb|fm|fi|fs)_[a-z]+).*"))throw bad("日报问数不接受SQL或表名");if(in.question().matches("(?s).*(执行|帮我|直接|立即|自动|代我).{0,10}(转账|付款|过账|审批|报税|调税|修改绩效).*"))throw bad("问数不能触发任何财务执行");if(!model.ready())return model.analyze(Map.of());
  // Reuse audited question persistence and the same immutable snapshot; the monthly label is only its partition month.
  return monthly.ask(new FinanceInsightModels.Question(in.requestId(),YearMonth.from(in.date()).toString(),in.hotelId(),in.expectedReportVersion(),"OVERVIEW",in.question(),true,in.snapshotId()));
 }
}
